                <span>🚀 {lang === 'vi' ? 'Mở Chuyến Đi & Bật Thủ Quỹ' : 'Open Trip & Split Treasury'}</span>
              </button>
            </div>
          </div>

          {/* Day Tabs */}
          <div className={styles.dayTabsRow}>
            {plan.days.map((d) => (
              <button
                key={d.dayNumber}
