        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  if (error && !trip) {
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100vh',
          background: '#f8fafc',
          padding: '24px',
          textAlign: 'center',
          gap: '16px',
        }}
      >
        <span style={{ fontSize: '40px' }}>⚠️</span>
        <h2 style={{ margin: 0, color: '#0f172a' }}>Không thể tải dữ liệu chuyến đi</h2>
        <p style={{ color: '#ef4444', maxWidth: '480px' }}>{error}</p>
        <button
          type="button"
          onClick={loadTreasuryData}
          style={{
            padding: '10px 20px',
            background: '#0284c7',
            color: '#fff',
            border: 'none',
            borderRadius: '8px',
            fontWeight: 700,
            cursor: 'pointer',
          }}
        >
          Thử lại
        </button>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: '#f8fafc' }}>
      <Navbar activeModule="treasury" />
      <div className={styles.treasuryLayout}>
      {/* 1. Left Sidebar Navigation */}
      <TripSidebar tripId={tripId} />

      {/* 2. Main Treasury Content */}
      <main className={styles.mainContainer}>
        {trip && (
          <TripHeader
            trip={trip}
            memberCount={members.length}
            onOpenAddExpense={() => setIsDrawerOpen(true)}
          />
        )}

        {/* 3. 4 Financial KPI Cards */}
        {summary && (
          <FinancialKpiCards
            summary={summary}
            memberCount={members.length}
            currentUserId={currentUserId}
          />
        )}

        {/* 4. Middle Section: Donut Chart + Settlement Matrix */}
        <div className={styles.twoColSection}>
          <ExpenseCategoryDonut
            expenses={expenses}
            totalSpent={summary?.totalSpent ?? 0}
          />

          {summary && (
            <DebtSettlementMatrix
              summary={summary}
              members={members}
              currentUserId={currentUserId}
            />
          )}
        </div>

        {/* 5. Bottom Section: Expense Ledger Table */}
        <ExpenseLedgerTable
          expenses={expenses}
          members={members}
          onOpenAddExpense={() => setIsDrawerOpen(true)}
          onDeleteExpense={handleDeleteExpense}
        />
      </main>

      {/* 6. Form Nguyên Chất - Slide-Over Drawer */}
      <AddExpenseDrawer
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
        members={members}
        currentUserId={currentUserId}
        onSubmit={handleCreateExpense}
      />

      {/* 7. Toast Notification */}
      {toastMessage && (
        <div className={styles.toastNotification}>
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  </div>
  );
}

