'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import styles from './Navbar.module.css';

export interface NavbarProps {
  activeModule?: 'explore' | 'map' | 'planner' | 'trips' | 'treasury' | 'community';
  lang?: 'vi' | 'en';
  onLangChange?: (lang: 'vi' | 'en') => void;
}

export function Navbar({
  activeModule = 'explore',
  lang: propLang,
  onLangChange,
}: NavbarProps) {
  const [internalLang, setInternalLang] = useState<'vi' | 'en'>('vi');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Sync language with localStorage or prop
  useEffect(() => {
    if (propLang) {
      setInternalLang(propLang);
    } else {
      try {
        const saved = localStorage.getItem('vista_lang');
        if (saved === 'vi' || saved === 'en') {
          setInternalLang(saved);
        }
      } catch {
        // SSR safe
      }
    }
  }, [propLang]);

  const toggleLanguage = () => {
    const nextLang = internalLang === 'vi' ? 'en' : 'vi';
    setInternalLang(nextLang);
    try {
      localStorage.setItem('vista_lang', nextLang);
    } catch {
      // ignore
    }
    if (onLangChange) {
      onLangChange(nextLang);
    }
  };

  const navItems = [
    {
      id: 'explore',
      labelVi: 'Khám phá điểm đến',
      labelEn: 'Destinations',
      href: '/',
      icon: '🧭',
      badge: null,
    },
    {
      id: 'map',
      labelVi: 'Bản đồ & GPS',
      labelEn: 'Map & GPS',
      href: '/map',
      icon: '📍',
      badge: null,
    },
    {
      id: 'planner',
      labelVi: 'AI Lập lịch trình',
      labelEn: 'AI Planner',
      href: '/planner',
      icon: '✨',
      badge: 'AI PRO',
      badgeType: 'ai',
    },
    {
      id: 'trips',
      labelVi: 'Tổ chức chuyến đi',
      labelEn: 'Group Trips',
      href: '/trips',
      icon: '🎒',
      badge: 'Nhóm',
      badgeType: 'group',
    },
    {
      id: 'treasury',
      labelVi: 'Thủ quỹ & Chia tiền',
      labelEn: 'Treasury & Split',
      href: '/trips/demo-danang-2026/treasury',
      icon: '💰',
      badge: null,
    },
