'use client';

import React, { useState } from 'react';
import type { TripExpenseSummary, TripMember } from '../types';
import styles from '../treasury.module.css';

interface DebtSettlementMatrixProps {
  summary: TripExpenseSummary;
  members: TripMember[];
  currentUserId?: string;
}

export function DebtSettlementMatrix({
  summary,
  members,
  currentUserId,
}: DebtSettlementMatrixProps) {
  const [selectedTransfer, setSelectedTransfer] = useState<{
    fromName: string;
    toName: string;
    amount: number;
  } | null>(null);

  const memberMap = new Map<string, TripMember>();
  members.forEach((m) => memberMap.set(m.userId, m));

  const formatVnd = (val: number) => {
    return new Intl.NumberFormat('vi-VN').format(Math.abs(Math.round(val))) + ' ₫';
  };

  const getMemberDisplayName = (userId: string) => {
    const mem = memberMap.get(userId);
    if (!mem) return 'Thành viên';
    if (userId === currentUserId) return `Bạn (${mem.displayName})`;
    return mem.displayName;
  };

  const deltas = summary.settlementDeltas || {};

  return (
    <div className={styles.sectionCard}>
      <div className={styles.sectionCardHeader}>
        <div>
          <h2 className={styles.sectionTitle}>Đối Soát Nợ Nhóm</h2>
          <div className={styles.sectionSubtitle}>
            Cân đối thu chi tối ưu giữa {members.length} thành viên
          </div>
        </div>
        <button
          type="button"
          className={styles.btnSecondary}
          style={{ fontSize: '12px', padding: '4px 10px' }}
          onClick={() => alert('Chi tiết đối soát nợ toàn đoàn')}
        >
          Xem chi tiết
        </button>
      </div>

      {/* Member Balances */}
      <div className={styles.settlementList}>
        {members.map((member) => {
          const delta = deltas[member.userId] !== undefined ? deltas[member.userId] : 0;
          const isMe = member.userId === currentUserId;
          const initial = member.displayName ? member.displayName.charAt(0).toUpperCase() : 'U';

          return (
            <div key={member.userId} className={styles.memberBalanceRow}>
              <div className={styles.memberInfo}>
                <div
                  className={styles.avatarCircle}
                  style={{ background: isMe ? '#0284c7' : '#64748b' }}
                >
                  {initial}
                </div>
                <span className={styles.memberName}>
                  {isMe ? `Bạn (${member.displayName})` : member.displayName}
                </span>
              </div>

              <div className={styles.balanceRight}>
                <span
                  className={`${styles.balanceAmount} ${
                    delta > 0
                      ? styles.balancePositive
                      : delta < 0
                      ? styles.balanceNegative
                      : ''
                  }`}
                >
                  {delta > 0 ? `+${formatVnd(delta)}` : delta < 0 ? `-${formatVnd(delta)}` : '0 ₫'}
                </span>
                <span
                  className={`${styles.balancePill} ${
                    delta > 0 ? styles.pillRefund : delta < 0 ? styles.pillPay : ''
                  }`}
                  style={{
                    background: delta === 0 ? '#f1f5f9' : undefined,
                    color: delta === 0 ? '#64748b' : undefined,
                  }}
                >
                  {delta > 0 ? 'Được hoàn lại' : delta < 0 ? 'Cần trả thêm' : 'Đã cân bằng'}
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {/* Suggested Min-Cash-Flow Transfers */}
      {summary.suggestedTransfers && summary.suggestedTransfers.length > 0 && (
        <div style={{ marginTop: '16px' }}>
          <div style={{ fontSize: '13px', fontWeight: 700, color: '#334155', marginBottom: '8px' }}>
            ⚡ Gợi ý chuyển khoản tối ưu (Min Cash Flow):
          </div>
          {summary.suggestedTransfers.map((t, idx) => {
            const fromName = getMemberDisplayName(t.fromUserId);
            const toName = getMemberDisplayName(t.toUserId);
            return (
              <div key={idx} className={styles.transferCard}>
                <div className={styles.transferText}>
                  <span className={styles.transferHighlight}>{fromName}</span> chuyển cho{' '}
                  <span className={styles.transferHighlight}>{toName}</span>: {formatVnd(t.amount)}
                </div>
                <button
                  type="button"
                  className={styles.vietQrBtn}
                  onClick={() =>
                    setSelectedTransfer({
                      fromName,
                      toName,
                      amount: t.amount,
                    })
                  }
                >
                  <span>QR</span>
                  <span>VietQR</span>
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* VietQR Modal */}
      {selectedTransfer && (
        <div
          className={styles.drawerOverlay}
          onClick={() => setSelectedTransfer(null)}
          style={{ alignItems: 'center', justifyContent: 'center' }}
        >
          <div
            className={styles.sectionCard}
            style={{ width: '380px', maxWidth: '90%', textAlign: 'center', padding: '24px' }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ margin: '0 0 12px 0', fontSize: '18px', fontWeight: 800, color: '#0f172a' }}>
              Thanh Toán VietQR Nhanh
            </h3>
            <p style={{ fontSize: '13px', color: '#64748b', margin: '0 0 16px 0' }}>
              Quét mã để chuyển tiền từ <b>{selectedTransfer.fromName}</b> đến{' '}
              <b>{selectedTransfer.toName}</b>
            </p>

            <div
              style={{
                width: '200px',
                height: '200px',
                margin: '0 auto 16px auto',
                background: '#ffffff',
                border: '1px solid #cbd5e1',
                borderRadius: '12px',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '12px',
                boxShadow: '0 4px 12px rgba(0,0,0,0.06)',
              }}
            >
              <img
                src={`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=https://vietqr.me/transfer?amount=${selectedTransfer.amount}`}
                alt="VietQR code"
                width={170}
                height={170}
                style={{ borderRadius: '8px' }}
              />
            </div>

            <div style={{ fontSize: '20px', fontWeight: 800, color: '#16a34a', marginBottom: '16px' }}>
              {formatVnd(selectedTransfer.amount)}
            </div>

            <button
              type="button"
              className={styles.btnSecondary}
              style={{ width: '100%', justifyContent: 'center' }}
              onClick={() => setSelectedTransfer(null)}
            >
              Đóng
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React from 'react';
import type { Expense } from '../types';
import styles from '../treasury.module.css';

interface ExpenseCategoryDonutProps {
  expenses: Expense[];
  totalSpent: number;
}

const CATEGORY_CONFIG: Record<
  string,
  { label: string; icon: string; color: string; bg: string }
> = {
  FOOD: { label: 'Ăn uống', icon: '🍜', color: '#f97316', bg: '#ffedd5' },
  ACCOMMODATION: { label: 'Lưu trú', icon: '🛏️', color: '#0284c7', bg: '#e0f2fe' },
  TRANSPORT: { label: 'Di chuyển', icon: '🚗', color: '#06b6d4', bg: '#cffafe' },
  ACTIVITIES: { label: 'Vé tham quan', icon: '🎟️', color: '#a855f7', bg: '#f3e8ff' },
  OTHER: { label: 'Mua sắm / Khác', icon: '🛍️', color: '#f43f5e', bg: '#ffe4e6' },
};

export function ExpenseCategoryDonut({ expenses, totalSpent }: ExpenseCategoryDonutProps) {
  // Aggregate real totals by category
  const categoryTotals: Record<string, number> = {
    FOOD: 0,
    ACCOMMODATION: 0,
    TRANSPORT: 0,
    ACTIVITIES: 0,
    OTHER: 0,
  };

  expenses.forEach((exp) => {
    const cat = exp.category || 'OTHER';
    if (categoryTotals[cat] !== undefined) {
      categoryTotals[cat] += Number(exp.amount) || 0;
    } else {
      categoryTotals['OTHER'] += Number(exp.amount) || 0;
    }
  });

  const formatVnd = (val: number) => {
    return new Intl.NumberFormat('vi-VN').format(Math.round(val)) + ' ₫';
  };

  // Build SVG Donut Segments
  const radius = 65;
  const strokeWidth = 24;
  const circumference = 2 * Math.PI * radius;

  let cumulativeOffset = 0;
  const segments = Object.entries(categoryTotals)
    .filter(([_, amount]) => amount > 0)
    .map(([catKey, amount]) => {
      const pct = totalSpent > 0 ? amount / totalSpent : 0;
      const strokeDasharray = `${pct * circumference} ${circumference}`;
      const strokeDashoffset = -cumulativeOffset;
      cumulativeOffset += pct * circumference;

      return {
        key: catKey,
        amount,
        pct: (pct * 100).toFixed(1),
        config: CATEGORY_CONFIG[catKey] || CATEGORY_CONFIG.OTHER,
        strokeDasharray,
        strokeDashoffset,
      };
    });

  return (
    <div className={styles.sectionCard}>
      <div className={styles.sectionCardHeader}>
        <div>
          <h2 className={styles.sectionTitle}>Phân Bổ Chi Tiêu</h2>
          <div className={styles.sectionSubtitle}>
            Tổng chi: {formatVnd(totalSpent)}
          </div>
        </div>
        <select className={styles.filterSelect} style={{ fontSize: '12px', padding: '4px 8px' }}>
          <option>Theo danh mục ▾</option>
        </select>
      </div>

      <div className={styles.donutContainer}>
        {/* SVG Donut Visual */}
        <div className={styles.donutVisualBox}>
          <svg width="170" height="170" viewBox="0 0 170 170" style={{ transform: 'rotate(-90deg)' }}>
            {/* Background Track */}
            <circle
              cx="85"
              cy="85"
              r={radius}
              fill="transparent"
              stroke="#f1f5f9"
              strokeWidth={strokeWidth}
            />
            {/* Active Segments */}
            {segments.map((seg) => (
              <circle
                key={seg.key}
                cx="85"
                cy="85"
                r={radius}
                fill="transparent"
                stroke={seg.config.color}
                strokeWidth={strokeWidth}
                strokeDasharray={seg.strokeDasharray}
                strokeDashoffset={seg.strokeDashoffset}
                strokeLinecap="butt"
              />
            ))}
          </svg>

          <div className={styles.donutCenterText}>
            <span className={styles.donutCenterAmount}>{formatVnd(totalSpent)}</span>
            <span className={styles.donutCenterLabel}>Tổng chi</span>
          </div>
        </div>

        {/* Legend Breakdown */}
        <div className={styles.legendList}>
          {Object.entries(CATEGORY_CONFIG).map(([key, config]) => {
            const amount = categoryTotals[key] || 0;
            const pct = totalSpent > 0 ? ((amount / totalSpent) * 100).toFixed(1) : '0.0';
            return (
              <div key={key} className={styles.legendRow}>
                <div className={styles.legendLeft}>
                  <div
                    className={styles.categoryIconPill}
                    style={{ background: config.bg, color: config.color }}
                  >
                    {config.icon}
                  </div>
                  <span>{config.label}</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center' }}>
                  <span className={styles.legendAmount}>{formatVnd(amount)}</span>
                  <span className={styles.legendPercent}>{pct}%</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import type { Expense, TripMember } from '../types';
import styles from '../treasury.module.css';

interface ExpenseLedgerTableProps {
  expenses: Expense[];
  members: TripMember[];
  onOpenAddExpense: () => void;
  onDeleteExpense: (expenseId: string) => Promise<void>;
}

const CATEGORY_MAP: Record<string, { label: string; icon: string; bg: string; color: string }> = {
  FOOD: { label: 'Ăn uống', icon: '🍜', bg: '#ffedd5', color: '#ea580c' },
  ACCOMMODATION: { label: 'Lưu trú', icon: '🛏️', bg: '#e0f2fe', color: '#0284c7' },
  TRANSPORT: { label: 'Di chuyển', icon: '🚗', bg: '#cffafe', color: '#0891b2' },
  ACTIVITIES: { label: 'Vé tham quan', icon: '🎟️', bg: '#f3e8ff', color: '#9333ea' },
  OTHER: { label: 'Mua sắm / Khác', icon: '🛍️', bg: '#ffe4e6', color: '#e11d48' },
};

export function ExpenseLedgerTable({
  expenses,
  members,
  onOpenAddExpense,
  onDeleteExpense,
}: ExpenseLedgerTableProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('ALL');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const memberMap = new Map<string, TripMember>();
  members.forEach((m) => memberMap.set(m.userId, m));

  const formatVnd = (val: number) => {
    return new Intl.NumberFormat('vi-VN').format(Math.round(val)) + ' ₫';
  };

  const formatDate = (isoString?: string) => {
    if (!isoString) return '--/--/----';
    const d = new Date(isoString);
    return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
  };

  const filteredExpenses = expenses.filter((exp) => {
    if (categoryFilter !== 'ALL' && exp.category !== categoryFilter) {
      return false;
    }
    if (searchTerm.trim()) {
      const q = searchTerm.toLowerCase();
      const titleMatch = exp.title.toLowerCase().includes(q);
      const payer = memberMap.get(exp.paidBy);
      const payerMatch = payer ? payer.displayName.toLowerCase().includes(q) : false;
      return titleMatch || payerMatch;
    }
    return true;
  });

  const handleDelete = async (id: string, title: string) => {
    if (!confirm(`Bạn có chắc chắn muốn hủy khoản chi "${title}"?`)) return;
    try {
      setDeletingId(id);
      await onDeleteExpense(id);
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div className={styles.sectionCard} style={{ marginTop: '24px' }}>
      <div className={styles.ledgerHeader}>
        <h2 className={styles.sectionTitle}>Nhật Ký Hóa Đơn</h2>

        <div className={styles.ledgerControls}>
          <input
            type="text"
            className={styles.searchInput}
            placeholder="🔍 Tìm kiếm theo mô tả, người chi..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />

          <select
            className={styles.filterSelect}
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            <option value="ALL">Tất cả danh mục ▾</option>
            <option value="FOOD">🍜 Ăn uống</option>
            <option value="ACCOMMODATION">🛏️ Lưu trú</option>
            <option value="TRANSPORT">🚗 Di chuyển</option>
            <option value="ACTIVITIES">🎟️ Vé tham quan</option>
            <option value="OTHER">🛍️ Khác</option>
          </select>

          <button
            type="button"
            className={styles.primaryAddBtn}
            onClick={onOpenAddExpense}
          >
            <span>+</span>
            <span>Ghi Khoản Chi Mới</span>
          </button>
        </div>
      </div>

      <div className={styles.tableWrapper}>
        <table className={styles.ledgerTable}>
          <thead>
            <tr>
              <th>Ngày</th>
              <th>Mô tả</th>
              <th>Danh mục</th>
              <th>Người chi</th>
              <th>Số tiền</th>
              <th>Chia đều cho</th>
              <th style={{ textAlign: 'right' }}>Thao tác</th>
            </tr>
          </thead>
          <tbody>
            {filteredExpenses.length > 0 ? (
              filteredExpenses.map((exp) => {
                const cat = CATEGORY_MAP[exp.category] || CATEGORY_MAP.OTHER;
                const payer = memberMap.get(exp.paidBy);
                const payerName = payer ? payer.displayName : 'Thành viên';
                const payerInitial = payerName.charAt(0).toUpperCase();
                const splitCount = exp.splits ? exp.splits.length : 1;

                return (
                  <tr key={exp.id}>
                    <td style={{ color: '#64748b' }}>{formatDate(exp.occurredAt)}</td>
                    <td className={styles.descBold}>{exp.title}</td>
                    <td>
                      <span
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '6px',
                          padding: '3px 8px',
                          borderRadius: '6px',
                          background: cat.bg,
                          color: cat.color,
                          fontWeight: 650,
                          fontSize: '12px',
                        }}
                      >
                        <span>{cat.icon}</span>
                        <span>{cat.label}</span>
                      </span>
                    </td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        <div
                          className={styles.avatarCircle}
                          style={{ width: '26px', height: '26px', fontSize: '11px' }}
                        >
                          {payerInitial}
                        </div>
                        <span style={{ fontWeight: 500 }}>{payerName}</span>
                      </div>
                    </td>
                    <td className={styles.amountBold}>{formatVnd(exp.amount)}</td>
                    <td style={{ color: '#64748b' }}>{splitCount} người</td>
                    <td style={{ textAlign: 'right' }}>
                      <button
                        type="button"
                        className={styles.deleteBtn}
                        onClick={() => handleDelete(exp.id, exp.title)}
                        disabled={deletingId === exp.id}
                        title="Hủy khoản chi"
                      >
                        {deletingId === exp.id ? '...' : '🗑️ Xóa'}
                      </button>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={7}>
                  <div className={styles.emptyStateBox}>
                    <span style={{ fontSize: '32px' }}>🧾</span>
                    <span style={{ fontWeight: 600, color: '#0f172a' }}>
                      Chưa có khoản chi tiêu nào
                    </span>
                    <span style={{ fontSize: '13px' }}>
                      Hãy nhấn nút <b>"+ Ghi Khoản Chi Mới"</b> để thêm khoản chi đầu tiên cho chuyến đi!
                    </span>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import type { TripDetail } from '../types';
import styles from '../treasury.module.css';

interface TripHeaderProps {
  trip: TripDetail;
  memberCount: number;
  onOpenAddExpense: () => void;
}

export function TripHeader({ trip, memberCount, onOpenAddExpense }: TripHeaderProps) {
  const formatDateRange = (start?: string, end?: string) => {
    if (!start || !end) return '24/10/2026 – 27/10/2026';
    const s = new Date(start);
    const e = new Date(end);
    const sStr = `${String(s.getDate()).padStart(2, '0')}/${String(s.getMonth() + 1).padStart(2, '0')}/${s.getFullYear()}`;
    const eStr = `${String(e.getDate()).padStart(2, '0')}/${String(e.getMonth() + 1).padStart(2, '0')}/${e.getFullYear()}`;
    return `${sStr} – ${eStr}`;
  };

  return (
    <header>
      <div className={styles.breadcrumbRow}>
        <span>‹</span>
        <span>Chuyến đi của nhóm</span>
      </div>

      <div className={styles.tripHeaderBox}>
        <div className={styles.tripTitleGroup}>
          <div className={styles.titleWithBadge}>
            <h1 className={styles.tripTitle}>{trip.title}</h1>
            <span style={{ cursor: 'pointer', fontSize: '18px' }} title="Chỉnh sửa">
              ✏️
            </span>
            <div className={styles.statusPill}>
              <span className={styles.statusDot} />
              <span>{trip.status === 'IN_PROGRESS' ? 'ĐANG DIỄN RA' : trip.status}</span>
            </div>
          </div>

          <div className={styles.tripMetaRow}>
            <div className={styles.tripMetaItem}>
              <span>📅</span>
              <span>{formatDateRange(trip.startDate, trip.endDate)}</span>
            </div>
            <span>•</span>
            <div className={styles.tripMetaItem}>
              <span>👥</span>
              <span>{memberCount} thành viên</span>
            </div>
          </div>
        </div>

        <div className={styles.headerActionButtons}>
          <button type="button" className={styles.btnSecondary} onClick={() => alert('Chỉnh sửa thông tin chuyến đi')}>
            <span>✏️</span>
            <span>Chỉnh sửa chuyến đi</span>
          </button>
          <button type="button" className={styles.btnSecondary} onClick={() => window.print()}>
            <span>📥</span>
            <span>Xuất báo cáo</span>
          </button>
          <button
            type="button"
            className={styles.btnSecondary}
            onClick={() => {
              if (navigator.clipboard) {
                navigator.clipboard.writeText(window.location.href);
                alert('Đã sao chép liên kết chuyến đi!');
              }
            }}
          >
            <span>🔗</span>
            <span>Chia sẻ</span>
          </button>
        </div>
      </div>
    </header>
  );
}

